SELECT s.STATENO, s.DOCUMENT_ID, s.triggering_doc_id TRIGG_DOC, Nvl2(d.test_type_cd, d.test_type_cd, d.document_type_code) as TRIGG_DOC_TYPE, to_char(w.start_date,'MM/DD/YYYY') WORKER_ASSIGNED_DATE, v.provider_facility_name LOCATION, v.provider_facility_addr ADDRESS, to_char (s.create_date, 'MM/DD/YYYY') EVENT_DATE, a.status_description CURRENT_ASSIGNMENT_STATUS, pkg_trk_common.fn_get_fullname(nu.LAST_NAME, nu.FIRST_NAME, nu.MIDDLE_NAME, NULL) WORKER_NAME, s.acrf_document_id ACRF_DOC_ID, s.pcrf_document_id PCRF_DOC_ID, doc.LAST_NAME, doc.FIRST_NAME, to_char(doc.date_of_birth, 'MM/DD/YYYY') DATE_OF_BIRTH, v.PROVIDER_FACILITY_COUNTY, v.PROVIDER_FACILITY_PHONE, s.CURRENT_ACTIVITY_TYPE_CODE, (SELECT flag_active FROM person WHERE stateno = s.stateno) STATENO_ACTIVE, d.is_active DOCUMENT_STATUS, s.AHI_FLAG FROM surveillance_assignment s, worker_assignment w, user_region r, TABLE(pkg_assignment.fn_assignment_address (s.document_id,s.assign_address_type)) v, coded_assignment_status a ,document_locator d ,document_person_attr doc ,std_hiv_eclrs_doc hiv ,nyehms_ehars_stateno_map m ,nyehms_users nu WHERE r.worker_region_id(+) = w.worker_region_id AND w.worker_assignment_id(+) = s.current_worker_assignment_id AND w.document_id = v.document_id(+) AND s.current_assignment_status = a.status_cd AND s.triggering_doc_id = d.document_id AND s.triggering_doc_id = doc.document_id AND s.triggering_doc_id = hiv.document_id(+) AND s.stateno = m.nyehms_stateno(+) AND r.worker_id = nu.worker_id(+) AND s.current_assignment_status = #{p_assignmentType} AND hiv.test_result(+) NOT IN ('NEG', 'NO RESULT', 'HIV NEGATIVE', '0') AND hiv.test_result(+) NOT LIKE '<%' AND d.document_type_code IN ('HIV_LAB','PRF') AND (m.hiv_cdc = 'Y' OR m.aids_cdc = 'Y')
AND ((SUBSTR (m.hiv_aids_dx_dt, 1, 4) in (
#{currentYear}
#{previousYear}
#{currentYear}, #{previousYear}
)) OR (m.hiv_aids_dx_dt IS NULL))
AND s.CURRENT_REGION_CD = ${p_regionCode}
AND r.worker_id = #{p_workerId}

